/* Kartu tanya-jawab untuk latihan aktif (active recall) */
window.BEFS_FLASHCARDS = [
  /* ---- CM1 ---- */
  { ch: 1, q: "Apa definisi business ethics menurut Crane & Matten?", a: "Studi tentang <strong>situasi, aktivitas, dan keputusan bisnis</strong> di mana isu <strong>benar dan salah</strong> dipertanyakan. Bukan soal legal/ilegal, bukan soal untung/rugi." },
  { ch: 1, q: "Bedakan morality, ethics, dan ethical theory.", a: "<strong>Morality</strong> = norma dan nilai yang tertanam secara sosial. <strong>Ethics</strong> = studi rasional atas moralitas. <strong>Ethical theory</strong> = aturan/prinsip hasil studi itu, misalnya utilitarianism." },
  { ch: 1, q: "Mengapa sesuatu yang legal belum tentu etis? Beri contoh.", a: "Hukum adalah kodifikasi moralitas yang <em>sudah</em> disepakati, sehingga selalu tertinggal dari isu baru. Contoh: <strong>tax avoidance</strong> agresif, membayar upah minimum yang di bawah upah layak, iklan makanan tinggi gula untuk anak." },
  { ch: 1, q: "Sebutkan tiga celah (gap) yang ditimbulkan globalisasi bagi etika bisnis.", a: "<strong>Cultural</strong> (nilai moral berbeda antarnegara), <strong>legal</strong> (tidak ada hukum global, muncul regulatory arbitrage), dan <strong>accountability</strong> (kepada siapa MNC bertanggung jawab)." },
  { ch: 1, q: "Apa beda ethical relativism dan ethical absolutism? Apa jalan tengahnya?", a: "<strong>Relativism</strong>: benar-salah bergantung budaya. <strong>Absolutism</strong>: ada prinsip universal yang berlaku di mana pun. Jalan tengahnya <strong>ethical pluralism</strong> — ada nilai inti yang tak bisa ditawar, sisanya menghormati konteks lokal." },
  { ch: 1, q: "Sebutkan definisi sustainable development menurut Brundtland Report.", a: "\"Development that meets the needs of the present <strong>without compromising the ability of future generations</strong> to meet their own needs\" (WCED, 1987)." },
  { ch: 1, q: "Apa itu triple bottom line dan apa jebakan menjawabnya?", a: "Tiga dimensi keberlanjutan: <strong>environmental, economic, social</strong> (planet, profit, people). Jebakannya: berhenti di tiga kata. Tambahkan bahwa ketiganya sering <strong>trade-off</strong>, dan dimensi sosial mencakup keadilan <strong>intra-</strong> dan <strong>antargenerasi</strong>." },
  { ch: 1, q: "Apakah \"does ethics pay?\" punya jawaban sederhana?", a: "Tidak. Korelasi kinerja sosial dan finansial lemah hingga sedang, dan arah sebabnya tidak jelas. Peringatan Crane & Matten: bila laba adalah satu-satunya alasan berperilaku etis, perilaku itu akan ditinggalkan begitu tidak menguntungkan." },

  /* ---- CM2 ---- */
  { ch: 2, q: "Apa argumen bahwa korporasi bisa menjadi moral agent?", a: "Korporasi punya <strong>Corporate Internal Decision Structure (CID)</strong> — bagan organisasi + aturan pengakuan keputusan — dan <strong>budaya organisasi</strong> yang bertahan meski orangnya berganti. Namun ini tidak menghapus tanggung jawab individu." },
  { ch: 2, q: "Sebutkan empat tingkat piramida CSR Carroll beserta status sosialnya.", a: "<strong>Economic</strong> (be profitable — required), <strong>Legal</strong> (obey the law — required), <strong>Ethical</strong> (be ethical — expected), <strong>Philanthropic</strong> (be a good corporate citizen — desired)." },
  { ch: 2, q: "Sebutkan tiga kritik terhadap piramida Carroll.", a: "(1) Bentuk piramida menyiratkan urutan prioritas, padahal keempatnya simultan dan sering bertabrakan; (2) berbasis konteks AS — di Eropa banyak tanggung jawab etis sudah menjadi hukum; (3) kategori etis dan filantropis sulit dipisahkan." },
  { ch: 2, q: "Apa tiga argumen Friedman menentang CSR?", a: "<strong>Agensi</strong> (manajer membelanjakan uang pemegang saham tanpa mandat), <strong>kompetensi</strong> (manajer tidak dilatih menyelesaikan masalah sosial), <strong>legitimasi</strong> (prioritas sosial adalah kewenangan pemerintah terpilih)." },
  { ch: 2, q: "Bagaimana membantah Friedman secara berimbang?", a: "Akui kekuatannya (soal legitimasi dan akuntabilitas), lalu bantah: perusahaan menikmati hak istimewa dari masyarakat; pasar punya eksternalitas; pemegang saham sendiri kini menuntut ESG; dan Friedman sendiri mensyaratkan kepatuhan pada <em>ethical custom</em>." },
  { ch: 2, q: "Apa beda primary dan secondary stakeholders?", a: "<strong>Primary (market) stakeholders</strong> terlibat transaksi ekonomi langsung: karyawan, pemegang saham &amp; investor, kreditor, pelanggan, pemasok, distributor. <strong>Secondary (nonmarket)</strong> tidak bertransaksi langsung tetapi memengaruhi/dipengaruhi: pemerintah, komunitas, media, LSM. Uji cepat: bila kelompok itu hilang dan operasi langsung terancam berhenti — ia primary." },
  { ch: 2, q: "Mengapa relasi perusahaan dan primary stakeholder digambarkan dengan panah dua arah?", a: "Karena tiap pihak <strong>memberi dan menerima</strong> — saling ketergantungan, bukan satu arah. Karyawan memberi tenaga dan menerima upah; pelanggan memberi pendapatan dan menerima produk yang aman. Ketika perusahaan menerima kontribusi tetapi menekan imbalannya, pertukaran berubah menjadi <em>ekstraksi</em> — di situlah persoalan etisnya." },
  { ch: 2, q: "Apa tiga level analisis etika bisnis menurut Velasquez?", a: "<strong>Systemic</strong> (moralitas sistem: kapitalisme, hukum, struktur industri), <strong>corporate</strong> (kebijakan dan budaya satu perusahaan), <strong>individual</strong> (keputusan dan karakter orang tertentu). Kasus besar hampir selalu memuat ketiganya — pilah per level saat menganalisis." },
  { ch: 2, q: "Apa beda negative right dan positive right?", a: "<strong>Negative right</strong>: pihak lain wajib <em>tidak mengganggu</em> (privasi, kebebasan berpendapat). <strong>Positive right</strong>: pihak lain wajib tidak mengganggu <em>dan menyediakan fasilitas</em> agar hak terlaksana (pendidikan dasar). Tafsir hak bisa bergeser — hak hidup dulu negatif, kini dibaca positif." },
  { ch: 2, q: "Sebutkan empat syarat moral sebuah kontrak.", a: "(1) Kedua pihak punya <strong>pengetahuan penuh</strong>; (2) tidak ada yang sengaja <strong>menyajikan fakta keliru</strong>; (3) tidak ada yang <strong>dipaksa</strong> masuk kontrak; (4) kontrak tidak mengikat pada <strong>tindakan tak bermoral</strong>. Uji ini tajam untuk kontrak gig economy, syarat layanan aplikasi, dan perjanjian pemasok kecil." },
  { ch: 2, q: "Apa beda private costs dan social costs, dan apa kewajiban etis perusahaan?", a: "<strong>Private costs</strong>: biaya perusahaan untuk memproduksi barang/jasanya. <strong>Social costs</strong>: biaya eksternal yang menjadi beban masyarakat (polusi, kerusakan iklim). Kewajibannya: <strong>internalize the external costs</strong> — hitung biaya sesungguhnya = private + social, dan pasang pengendali polusi." },
  { ch: 2, q: "Apa isi TBL versi Savitz dan bedanya dari Elkington?", a: "Savitz menurunkan TBL ke <strong>metrik terukur</strong>: Economics (penjualan, laba, ROI, pajak, lapangan kerja), Environment (kualitas udara-air, energi, limbah), Social (praktik kerja, dampak komunitas, HAM, tanggung jawab produk). Elkington memberi konsepnya (people-planet-profit); Savitz memberi indikator operasionalnya." },
  { ch: 2, q: "Apa definisi stakeholder menurut Freeman?", a: "\"Any group or individual who <strong>can affect or is affected by</strong> the achievement of the organization's objectives.\" Perhatikan dua arahnya." },
  { ch: 2, q: "Sebutkan tiga pendekatan stakeholder theory.", a: "<strong>Normative</strong> (mengapa ini benar secara moral), <strong>descriptive</strong> (apa yang sebenarnya terjadi), <strong>instrumental</strong> (apa untungnya bagi kinerja perusahaan)." },
  { ch: 2, q: "Apa tiga atribut dalam model stakeholder salience?", a: "<strong>Power</strong>, <strong>legitimacy</strong>, <strong>urgency</strong>. Satu atribut = latent; dua = expectant; tiga = <strong>definitive stakeholder</strong> (prioritas utama)." },
  { ch: 2, q: "Apa beda responsibility dan accountability?", a: "<strong>Responsibility</strong> bersifat ke depan: apa yang seharusnya kita lakukan. <strong>Accountability</strong> bersifat ke belakang: kepada siapa kita menjelaskan apa yang sudah dilakukan, dan sanksi apa bila gagal." },
  { ch: 2, q: "Jelaskan extended view of corporate citizenship.", a: "Pandangan khas Crane & Matten: korporasi <strong>mengelola hak kewarganegaraan</strong> individu ketika negara mundur — sebagai <em>provider</em> hak sosial, <em>enabler</em> hak sipil, dan <em>channel</em> hak politik." },

  /* ---- CM3 ---- */
  { ch: 3, q: "Apa beda teori normatif dan deskriptif?", a: "<strong>Normatif</strong> menjawab \"apa yang <em>seharusnya</em> dilakukan\" (CM3). <strong>Deskriptif</strong> menjawab \"apa yang <em>sebenarnya</em> terjadi saat orang memutuskan\" (CM4)." },
  { ch: 3, q: "Apa dasar pembeda consequentialist dan non-consequentialist?", a: "<strong>Consequentialist</strong>: benar-salah ditentukan oleh <em>hasil</em> (egoism, utilitarianism). <strong>Non-consequentialist</strong>: ditentukan oleh <em>prinsip/motif</em> (ethics of duty, ethics of rights & justice)." },
  { ch: 3, q: "Apa prinsip utilitarianism dan siapa tokohnya?", a: "\"The greatest good for the greatest number\" — tindakan benar bila memaksimalkan utilitas kolektif. Tokoh: <strong>Jeremy Bentham</strong> dan <strong>John Stuart Mill</strong>." },
  { ch: 3, q: "Sebutkan tiga kelemahan utilitarianism.", a: "(1) <strong>Subjectivity/quantification</strong> — sulit mengukur dan membandingkan kebahagiaan; (2) <strong>problem of distribution</strong> — total bisa maksimal sambil sangat tidak adil; (3) sulit <strong>memprediksi konsekuensi</strong>, terutama jangka panjang." },
  { ch: 3, q: "Apa beda act dan rule utilitarianism?", a: "<strong>Act</strong>: menilai tiap tindakan individual berdasarkan utilitasnya pada situasi itu. <strong>Rule</strong>: menilai apakah <em>aturan</em> di baliknya memaksimalkan utilitas bila diikuti semua orang." },
  { ch: 3, q: "Sebutkan tiga maksim categorical imperative Kant.", a: "(1) <strong>Consistency</strong> — bertindaklah menurut prinsip yang bisa menjadi hukum universal; (2) <strong>Human dignity</strong> — perlakukan manusia sebagai tujuan, tidak pernah semata sebagai sarana; (3) <strong>Universality</strong> — bertindaklah sebagai anggota pembuat hukum dalam kingdom of ends." },
  { ch: 3, q: "Mengapa maxim 2 Kant paling berguna untuk kasus bisnis?", a: "Ia langsung mengenai iklan menyesatkan, kerja paksa, dan eksploitasi data. Perhatikan kata <em>\"semata-mata\"</em>: mempekerjakan orang tidak otomatis salah — yang salah adalah memperlakukan mereka <em>hanya</em> sebagai alat, tanpa menghormati martabat dan otonominya." },
  { ch: 3, q: "Apa itu veil of ignorance dan dua prinsip Rawls?", a: "Rancang aturan tanpa tahu akan lahir sebagai siapa. Prinsipnya: (1) <strong>liberty principle</strong> — kebebasan dasar setara untuk semua; (2) <strong>difference principle</strong> — ketimpangan hanya dibenarkan bila memberi manfaat terbesar bagi yang paling tidak beruntung." },
  { ch: 3, q: "Apa beda fair procedure (Nozick) dan fair outcome (Rawls)?", a: "<strong>Nozick</strong>: adil bila prosesnya adil — hasil timpang tetap adil bila diperoleh secara sah. <strong>Rawls</strong>: adil bila hasilnya adil — ketimpangan harus menguntungkan yang paling lemah." },
  { ch: 3, q: "Sebutkan empat teori etika kontemporer dan fokus masing-masing.", a: "<strong>Virtue ethics</strong> (karakter — \"orang seperti apa saya?\"), <strong>feminist/care ethics</strong> (relasi dan tanggung jawab merawat), <strong>discourse ethics</strong> (dialog bebas dominasi — Habermas), <strong>postmodern ethics</strong> (moral impulse, intuisi, kecurigaan pada aturan birokratis)." },
  { ch: 3, q: "Apa lima langkah template analisis kasus etis?", a: "(1) Identifikasi dilemanya; (2) petakan stakeholder dan klaim yang bertabrakan; (3) terapkan minimal tiga lensa teori; (4) tambahkan lensa kontemporer bila relevan; (5) <strong>ambil posisi</strong>, akui trade-off, tawarkan alternatif solusi." },

  /* ---- CM4 ---- */
  { ch: 4, q: "Sebutkan empat tahap model pengambilan keputusan etis.", a: "(1) <strong>Recognize</strong> moral issue; (2) make moral <strong>judgement</strong>; (3) establish moral <strong>intent</strong>; (4) engage in moral <strong>behaviour</strong>. Rantai bisa putus di tahap mana pun." },
  { ch: 4, q: "Apa itu ethical blindness dan di tahap mana ia terjadi?", a: "Gagal melihat bahwa situasi mengandung persoalan moral — dianggap keputusan teknis, hukum, atau finansial belaka. Terjadi di <strong>tahap 1</strong>, dan merupakan kegagalan paling umum." },
  { ch: 4, q: "Sebutkan enam komponen moral intensity (Jones).", a: "<strong>Magnitude of consequences, social consensus, probability of effect, temporal immediacy, proximity, concentration of effect.</strong>" },
  { ch: 4, q: "Komponen moral intensity mana yang menjelaskan mengapa krisis iklim sulit ditangani?", a: "<strong>Temporal immediacy</strong> (dampaknya jauh di masa depan) dan <strong>proximity</strong> (korbannya jauh secara sosial dan geografis) — keduanya rendah, sehingga isu terasa kurang mendesak secara moral." },
  { ch: 4, q: "Sebutkan tiga level cognitive moral development Kohlberg.", a: "<strong>Pre-conventional</strong> (tahap 1–2: hukuman dan kepentingan diri), <strong>conventional</strong> (3–4: harapan kelompok dan hukum — mayoritas orang dewasa), <strong>post-conventional</strong> (5–6: kontrak sosial dan prinsip universal)." },
  { ch: 4, q: "Apa kritik utama terhadap Kohlberg?", a: "<strong>Bias gender</strong> (Carol Gilligan: model dibangun dari sampel laki-laki dan mengistimewakan penalaran keadilan di atas penalaran <em>care</em>), bias budaya Barat, dan kesenjangan antara penalaran dan tindakan nyata." },
  { ch: 4, q: "Apa itu moral imagination dan mengapa penting?", a: "Kemampuan membayangkan <strong>alternatif di luar pilihan yang tampak tersedia</strong> dan melihat dari sudut pandang pihak lain. Penting karena mengubah dilema biner \"untung atau etis\" menjadi pencarian opsi ketiga — inti dari CO3." },
  { ch: 4, q: "Apa empat efek birokrasi terhadap moralitas?", a: "<strong>Suppression of moral autonomy</strong>, <strong>instrumental morality</strong> (fokus cara bukan tujuan), <strong>segmentation of responsibility</strong> (tak seorang pun merasa bertanggung jawab utuh), <strong>denial of moral status</strong> (orang direduksi jadi angka)." },
  { ch: 4, q: "Apa itu moral muteness dan euphemistic labelling?", a: "<strong>Moral muteness</strong>: manajer menghindari bahasa moral karena dianggap tidak profesional dan mengurangi fleksibilitas. <strong>Euphemistic labelling</strong>: menyebut PHK sebagai \"rightsizing\" atau suap sebagai \"biaya administrasi\" — menumpulkan sensitivitas moral." },
  { ch: 4, q: "Apa dua pilar ethical leadership menurut Treviño?", a: "<strong>Moral person</strong> (siapa dirinya: integritas, perilaku, cara memutuskan) dan <strong>moral manager</strong> (apa yang ia lakukan: menjadi role model, mengomunikasikan etika, menegakkan reward & discipline)." },
  { ch: 4, q: "Mengapa \"ethically neutral leader\" tetap bermasalah?", a: "Pribadinya baik tetapi tidak pernah membicarakan etika. Karyawan mengisi kekosongan itu dengan asumsi bahwa yang penting hanya hasil. Pelajarannya: <strong>menjadi orang baik saja tidak cukup</strong> untuk memimpin secara etis." },
  { ch: 4, q: "Tipe pemimpin mana yang paling merusak, dan mengapa?", a: "<strong>Hypocritical leader</strong> — banyak bicara etika tetapi perilakunya buruk. Lebih merusak daripada diam karena menghancurkan kepercayaan pada seluruh program etika perusahaan." },

  /* ---- CM5 ---- */
  { ch: 5, q: "Apa beda pendekatan compliance-based dan integrity-based (Paine)?", a: "<strong>Compliance</strong>: mencegah pelanggaran hukum lewat aturan rinci, pemantauan, sanksi. <strong>Integrity</strong>: mendorong perilaku bertanggung jawab lewat nilai bersama dan kepemimpinan. Perusahaan baik menggabungkan keduanya." },
  { ch: 5, q: "Sebutkan empat jenis codes of ethics.", a: "<strong>Organizational/corporate</strong> (satu perusahaan), <strong>professional</strong> (asosiasi profesi), <strong>industry</strong> (satu sektor), <strong>programme/group</strong> (badan lintas pihak seperti Fairtrade atau UN Global Compact)." },
  { ch: 5, q: "Apa yang menentukan efektivitas kode etik?", a: "Bukan keberadaannya. Yang menentukan: isi yang spesifik, proses penyusunan yang melibatkan karyawan, komunikasi dan pelatihan, <strong>penegakan konsisten termasuk pada eksekutif senior</strong>, dan keselarasan dengan sistem imbalan." },
  { ch: 5, q: "Mengapa Enron menjadi contoh kegagalan kode etik?", a: "Enron punya kode etik setebal 64 halaman yang memenangkan penghargaan, tetapi budaya dan sistem imbalannya mendorong sebaliknya. Kode etik tanpa budaya dan penegakan hanyalah dokumen." },
  { ch: 5, q: "Apa definisi whistleblowing?", a: "Pengungkapan oleh anggota organisasi atas praktik <strong>ilegal, tidak bermoral, atau tidak sah</strong> yang berada di bawah kendali atasan mereka, kepada pihak yang mampu bertindak. Bisa internal atau eksternal." },
  { ch: 5, q: "Sebutkan lima kriteria whistleblowing yang dibenarkan (De George).", a: "(1) Praktik menimbulkan <strong>bahaya serius</strong>; (2) sudah <strong>melapor ke atasan langsung</strong>; (3) sudah <strong>menempuh saluran internal</strong> hingga habis; (4) ada <strong>bukti terdokumentasi</strong>; (5) ada alasan kuat bahwa pengungkapan akan <strong>mengubah keadaan</strong>." },
  { ch: 5, q: "Sebutkan empat tingkat tangga keterlibatan stakeholder.", a: "<strong>Informing</strong> (satu arah) → <strong>consultation</strong> (ditanya, tetap diputuskan sendiri) → <strong>dialogue</strong> (dua arah, posisi bisa berubah) → <strong>partnership</strong> (berbagi keputusan dan sumber daya)." },
  { ch: 5, q: "Apa itu tokenism dalam keterlibatan stakeholder?", a: "Konsultasi yang hasilnya sudah ditentukan sebelumnya. Ia menyerap kritik tanpa mengubah apa pun, dan meruntuhkan kepercayaan lebih dalam daripada tidak berkonsultasi sama sekali. Uji: apakah keputusan perusahaan <em>pernah berubah</em> karena masukan?" },
  { ch: 5, q: "Apa itu social accounting dan tiga aktivitasnya?", a: "Proses mengumpulkan, menganalisis, dan mengomunikasikan informasi dampak sosial dan lingkungan kepada stakeholder. Tiga aktivitas: <strong>accounting</strong> (mencatat), <strong>auditing</strong> (memverifikasi), <strong>reporting</strong> (melaporkan)." },
  { ch: 5, q: "Sebutkan empat standar pelaporan keberlanjutan utama.", a: "<strong>GRI Standards</strong> (paling luas dipakai), <strong>AA1000</strong> (inclusivity, materiality, responsiveness, impact), <strong>ISO 26000</strong> (panduan, bukan sertifikasi), <strong>SASB/ISSB & TCFD</strong> (berorientasi investor)." },
  { ch: 5, q: "Apa kriteria kualitas laporan keberlanjutan yang serius?", a: "<strong>Completeness</strong>, <strong>comparability</strong>, <strong>accuracy & verifiability</strong>, <strong>external assurance</strong> (pembeda paling tajam), dan <strong>balance</strong> — memuat kegagalan, bukan hanya cerita sukses." },
  { ch: 5, q: "Apa tanda-tanda greenwashing?", a: "Klaim tanpa angka, tanpa target berbatas waktu, tanpa verifikasi independen, dan laporan yang tidak memuat satu pun kegagalan atau target yang meleset." },

  /* ---- CM6 ---- */
  { ch: 6, q: "Apa itu agency problem dan dua penyebabnya?", a: "Pemegang saham (principal) mendelegasikan pengelolaan ke manajemen (agent). Penyebabnya: <strong>perbedaan kepentingan</strong> dan <strong>asimetri informasi</strong>. Biaya mengatasinya disebut <strong>agency cost</strong>." },
  { ch: 6, q: "Sebutkan hak-hak dasar pemegang saham.", a: "Hak atas <strong>informasi</strong> yang benar dan tepat waktu, hak <strong>memilih</strong> dewan dan memberi suara, hak atas <strong>bagian keuntungan</strong>, dan hak atas <strong>perlakuan setara</strong> — termasuk perlindungan pemegang saham minoritas." },
  { ch: 6, q: "Bandingkan governance Anglo-American dan Continental European.", a: "<strong>Anglo-American</strong>: kepemilikan tersebar, <em>unitary board</em>, kendali lewat pasar modal, orientasi jangka pendek-menengah. <strong>Continental</strong>: kepemilikan terkonsentrasi, dewan <em>dua tingkat</em>, kendali lewat relasi jangka panjang, ada <em>codetermination</em>." },
  { ch: 6, q: "Sistem governance mana yang dianut Indonesia, dan apa isu khasnya?", a: "Sistem <strong>dua tingkat</strong> — Dewan Komisaris dan Direksi — mirip model Kontinental. Isu khasnya: kepemilikan terkonsentrasi pada kelompok keluarga, sehingga muncul persoalan perlindungan pemegang saham minoritas dan <em>related-party transactions</em>." },
  { ch: 6, q: "Apa argumen kritis terhadap gaji eksekutif yang sangat tinggi?", a: "Rasio terhadap pekerja melonjak tanpa lonjakan kinerja sepadan; opsi saham mendorong <strong>manipulasi jangka pendek</strong> dan pengambilan risiko berlebihan; <strong>rewards for failure</strong>; komite remunerasi sering diisi sesama CEO." },
  { ch: 6, q: "Mengapa insider trading dianggap tidak etis? Beri tiga alasan.", a: "(1) Melanggar <strong>keadilan</strong> — sebagian pihak bermain dengan kartu terbuka; (2) merupakan <strong>penyalahgunaan informasi</strong> yang bukan miliknya; (3) menggerus <strong>kepercayaan</strong> pada pasar." },
  { ch: 6, q: "Apa beda tax evasion dan tax avoidance? Mengapa avoidance tetap dipersoalkan?", a: "<strong>Evasion</strong> ilegal (menyembunyikan penghasilan). <strong>Avoidance</strong> legal (transfer pricing, memindahkan laba). Avoidance dipersoalkan karena perusahaan menikmati infrastruktur yang dibiayai pajak lalu memindahkan bebannya — gagal uji maksim Kant 1." },
  { ch: 6, q: "Sebutkan tiga strategi SRI/ESG.", a: "<strong>Negative screening</strong> (mengeluarkan sektor tertentu), <strong>positive/best-in-class</strong> (memilih kinerja ESG terbaik per sektor), <strong>engagement & impact</strong> (menekan perubahan dari dalam sebagai pemegang saham)." },
  { ch: 6, q: "Sebutkan tiga kritik terhadap ESG.", a: "(1) <strong>Inkonsistensi rating</strong> antarlembaga pemeringkat; (2) mengukur risiko keberlanjutan <em>terhadap perusahaan</em>, bukan dampak <em>perusahaan terhadap dunia</em> (<strong>double materiality</strong>); (3) <strong>greenwashing produk keuangan</strong>." },
  { ch: 6, q: "Apa itu short-termism dan bagaimana responsnya?", a: "Tekanan laporan kuartalan mendorong orientasi jangka pendek, sementara isu keberlanjutan berjangka sangat panjang. Respons: hak suara ganda untuk pemegang jangka panjang, <em>integrated reporting</em>, mandat stewardship, dan <strong>benefit corporation</strong>." },

  /* ---- CM7 ---- */
  { ch: 7, q: "Sebutkan enam hak karyawan.", a: "Bebas dari <strong>diskriminasi</strong>, <strong>privasi</strong> dan martabat, tempat kerja <strong>sehat dan aman</strong>, <strong>upah adil</strong> dan jam kerja wajar, <strong>kebebasan berserikat</strong>, dan <strong>due process</strong>." },
  { ch: 7, q: "Sebutkan kewajiban karyawan terhadap perusahaan.", a: "Mematuhi kontrak dan bekerja kompeten, menghindari <strong>conflict of interest</strong>, menjaga kerahasiaan yang sah, tidak menyalahgunakan aset perusahaan, kejujuran, dan <strong>loyalitas dalam batas wajar</strong>." },
  { ch: 7, q: "Di mana batas kewajiban loyalitas karyawan?", a: "Loyalitas berhenti ketika perusahaan meminta karyawan <strong>berpartisipasi dalam atau menutupi tindakan yang membahayakan pihak lain</strong>. Di titik itu whistleblowing menjadi dapat dibenarkan." },
  { ch: 7, q: "Apa beda direct dan indirect discrimination?", a: "<strong>Direct</strong>: perlakuan berbeda secara terang-terangan berdasarkan karakteristik terlarang. <strong>Indirect</strong>: aturan yang tampak netral tetapi berdampak tidak proporsional pada kelompok tertentu — misalnya syarat tinggi badan yang tidak relevan." },
  { ch: 7, q: "Apa argumen pro dan kontra affirmative action?", a: "<strong>Pro</strong>: memperbaiki ketidakadilan historis; kesempatan formal tidak cukup bila titik berangkat tidak setara; keberagaman meningkatkan kualitas keputusan. <strong>Kontra</strong>: <em>reverse discrimination</em>; melanggar meritokrasi; dapat menstigma penerima manfaat." },
  { ch: 7, q: "Sebutkan empat uji kelayakan pemantauan karyawan.", a: "<strong>Justification</strong> (ada kepentingan bisnis yang sah?), <strong>proportionality</strong> (sepadan dengan risiko?), <strong>transparency</strong> (karyawan tahu?), <strong>consent & recourse</strong> (persetujuan bermakna dan ada saluran keberatan?)." },
  { ch: 7, q: "Mengapa argumen \"karyawan sudah setuju di kontrak\" lemah secara etis?", a: "Karena <strong>asimetri kuasa</strong> — menolak bisa berarti kehilangan pekerjaan, sehingga persetujuannya tidak bebas. Kaitkan dengan maksim Kant 2: apakah karyawan diperlakukan sebagai tujuan atau semata alat produksi?" },
  { ch: 7, q: "Apa beda minimum wage dan living wage?", a: "<strong>Minimum wage</strong>: batas bawah legal yang ditetapkan pemerintah. <strong>Living wage</strong>: upah yang cukup memenuhi kebutuhan dasar pekerja dan keluarganya. Selisihnya adalah contoh sempurna \"legal tetapi tidak etis\"." },
  { ch: 7, q: "Apa pelajaran etis dari kasus Rana Plaza (2013)?", a: "Lebih dari 1.100 pekerja garmen tewas saat gedung runtuh meski retakan sudah terlihat. Merek global tidak memiliki gedung itu, tetapi tekanan harga dan tenggat mereka ikut membentuk kondisinya — bukti <strong>extended responsibility</strong> melampaui batas kepemilikan hukum." },
  { ch: 7, q: "Apa itu just transition?", a: "Prinsip bahwa ketika perusahaan beralih dari energi fosil ke energi bersih, pekerja sektor lama tidak boleh ditinggalkan. Ini titik pertemuan langsung antara pilar <strong>lingkungan</strong> dan pilar <strong>sosial</strong> pada triple bottom line." },
  { ch: 7, q: "Mengapa gig economy menjadi isu etis?", a: "Pekerja platform diklasifikasikan sebagai mitra independen sehingga berada di luar jangkauan hak ketenagakerjaan — padahal tingkat kendali platform atas mereka menyerupai hubungan kerja. Isu besar bagi pengemudi dan kurir aplikasi di Indonesia." },

  /* ---- CM8 ---- */
  { ch: 8, q: "Sebutkan empat hak konsumen menurut Kennedy (1962).", a: "<strong>Right to safety</strong>, <strong>right to be informed</strong>, <strong>right to choose</strong>, <strong>right to be heard</strong>. Perluasannya: redress, consumer education, basic needs, healthy environment." },
  { ch: 8, q: "Apa tiga syarat consumer sovereignty benar-benar berlaku?", a: "<strong>Capability</strong> (konsumen mampu menilai), <strong>information</strong> (tersedia dan dapat dipahami), <strong>choice</strong> (ada alternatif nyata). Bila salah satu tidak terpenuhi, argumen \"konsumen kan memilih sendiri\" kehilangan kekuatannya." },
  { ch: 8, q: "Jelaskan caveat emptor, due care, dan strict liability.", a: "<strong>Caveat emptor</strong>: risiko pada pembeli. <strong>Due care</strong>: produsen wajib mengambil langkah wajar mencegah bahaya; bertanggung jawab bila lalai. <strong>Strict liability</strong>: bertanggung jawab atas cacat produk <em>meski tidak lalai</em>." },
  { ch: 8, q: "Apa beda deception dan puffery?", a: "<strong>Deception</strong>: klaim palsu, penghilangan informasi material, atau penyajian yang menciptakan kesan keliru — termasuk <em>half-truth</em>. <strong>Puffery</strong>: pujian berlebihan yang tidak dimaksudkan dipercaya harfiah; umumnya sah, kecuali menyangkut klaim kesehatan." },
  { ch: 8, q: "Mengapa iklan untuk anak dipersoalkan secara etis?", a: "Anak belum mampu mengenali maksud persuasif iklan, sehingga syarat <strong>capability</strong> pada consumer sovereignty tidak terpenuhi. Karena itu banyak negara membatasi iklan makanan tinggi gula, garam, dan lemak untuk anak." },
  { ch: 8, q: "Sebutkan lima isu etis dalam penetapan harga.", a: "<strong>Price fixing</strong>, <strong>predatory pricing</strong>, <strong>price gouging</strong> (menaikkan harga ekstrem saat darurat), <strong>deceptive pricing</strong> (termasuk drip pricing), dan <strong>personalized pricing</strong> berbasis data." },
  { ch: 8, q: "Sebutkan empat isu etis privasi data konsumen.", a: "<strong>Pengumpulan berlebihan</strong> (lawan: data minimisation), <strong>consent yang tidak bermakna</strong> (dark patterns), <strong>penggunaan sekunder</strong>, dan <strong>profiling & manipulasi</strong> berbasis kerentanan psikologis." },
  { ch: 8, q: "Apa pelajaran dari kasus Cambridge Analytica?", a: "Data puluhan juta pengguna dipakai membuat profil psikologis untuk penargetan politik tanpa persetujuan. Pelanggaran <strong>maksim Kant 2</strong> dalam bentuk paling murni — orang diperlakukan semata sebagai sarana memenangkan pemilu." },
  { ch: 8, q: "Mengapa kasus Nestlé susu formula menjadi contoh klasik?", a: "Pemasaran agresif di negara berkembang mendorong ibu berhenti menyusui; di lingkungan tanpa air bersih, susu formula justru meningkatkan kematian bayi. Contoh eksploitasi <strong>vulnerable consumers</strong>; memicu WHO Code." },
  { ch: 8, q: "Apa janji dan kritik pendekatan Bottom of the Pyramid?", a: "<strong>Janji</strong>: akses pada produk terjangkau, inovasi berbiaya rendah, memandang kelompok miskin sebagai mitra. <strong>Kritik</strong>: risiko eksploitasi, <em>poverty penalty</em>, mendorong konsumsi tak perlu dan jeratan utang." },
  { ch: 8, q: "Apa itu attitude–behaviour gap dalam konsumsi berkelanjutan?", a: "Konsumen menyatakan peduli lingkungan tetapi tetap membeli berdasarkan harga dan kenyamanan. Karena itu mengalihkan seluruh tanggung jawab keberlanjutan kepada \"pilihan konsumen\" adalah pengalihan tanggung jawab yang tidak jujur." },

  /* ---- CM9 ---- */
  { ch: 9, q: "Sebutkan empat isu etis dalam hubungan dengan pemasok.", a: "<strong>Misuse of power</strong> (menekan pemasok kecil), <strong>late payment</strong>, <strong>negotiation ethics</strong> (batas taktik sah dan penipuan), <strong>conflict of interest</strong> lewat hadiah dan relasi pribadi." },
  { ch: 9, q: "Apa beda bribery dan corruption?", a: "<strong>Bribery</strong>: menawarkan/menerima keuntungan sebagai imbalan atas tindakan ilegal, tidak etis, atau melanggar kepercayaan. <strong>Corruption</strong> lebih luas: penyalahgunaan kekuasaan yang dipercayakan untuk keuntungan pribadi." },
  { ch: 9, q: "Mengapa suap gagal uji maksim Kant 1?", a: "Suap <strong>tidak dapat diuniversalkan</strong> — bila semua orang menyuap, sistemnya runtuh dan suap kehilangan gunanya. Suap secara inheren mensyaratkan orang lain <em>tidak</em> melakukannya." },
  { ch: 9, q: "Apa itu facilitation payment dan bagaimana status hukumnya?", a: "Pembayaran kecil untuk mempercepat layanan rutin yang memang menjadi hak pembayar. <strong>Diizinkan bersyarat</strong> oleh US FCPA, tetapi <strong>dilarang</strong> oleh UK Bribery Act dan hukum Indonesia." },
  { ch: 9, q: "Sebutkan lima uji kelayakan pemberian hadiah bisnis.", a: "<strong>Nilai</strong> (wajar dan proporsional?), <strong>waktu</strong> (sedang ada tender?), <strong>transparansi</strong> (dicatat dan diketahui atasan?), <strong>timbal balik</strong> (menciptakan ekspektasi imbalan?), <strong>norma</strong> (sesuai kebijakan kedua organisasi?)." },
  { ch: 9, q: "Apa beda competitive intelligence dan industrial espionage?", a: "<strong>Intelligence</strong> (sah): menganalisis laporan tahunan, paten, iklan, riset pasar terbuka. <strong>Espionage</strong> (tidak sah): meretas, mencuri dokumen, menyamar sebagai pelanggan atau pelamar untuk menggali rahasia." },
  { ch: 9, q: "Sebutkan bentuk-bentuk perilaku antipersaingan.", a: "<strong>Cartel & price fixing</strong> (termasuk bid rigging), <strong>abuse of dominant position</strong> (predatory pricing, tying), <strong>dirty tricks</strong>, dan <strong>killer acquisition</strong>. Di Indonesia diawasi KPPU (UU No. 5/1999)." },
  { ch: 9, q: "Mengapa persaingan keras bukan pelanggaran etika?", a: "Persaingan justru manfaat utama pasar bagi konsumen. Yang tidak etis adalah upaya <strong>menghindari persaingan</strong> (kartel) atau <strong>menang dengan cara di luar kualitas penawaran</strong> (spionase, fitnah, penyalahgunaan dominasi)." },
  { ch: 9, q: "Apa itu extended responsibility dalam rantai pasok?", a: "Tanggung jawab perusahaan tidak berhenti pada <strong>batas kepemilikan hukum</strong>, melainkan meluas ke seluruh rantai nilai — ke hulu (pemasok tier 2–3, tambang, kebun) dan ke hilir (penggunaan dan pembuangan produk)." },
  { ch: 9, q: "Apa kelemahan supplier codes of conduct dan audit?", a: "Audit terjadwal mudah disiapkan; biaya kepatuhan sering dibebankan ke pemasok tanpa kenaikan harga beli; dan memutus kontrak setelah audit gagal justru sering merugikan pekerja. Perlu <strong>capacity building</strong>, bukan sekadar pengawasan." },
  { ch: 9, q: "Apa yang dijamin sertifikasi Fairtrade?", a: "<strong>Harga minimum</strong> yang menutup biaya produksi berkelanjutan, <strong>premium</strong> untuk pembangunan komunitas, hubungan dagang jangka panjang, prapembayaran, serta standar kerja dan lingkungan." },
  { ch: 9, q: "Apa hierarki prinsip circular economy?", a: "<strong>Refuse, reduce, reuse, repair, refurbish, remanufacture, recycle, recover</strong> — daur ulang justru hampir di urutan terakhir, karena mencegah penggunaan material selalu lebih baik daripada mengolahnya kembali." },

  /* ---- CM10 ---- */
  { ch: 10, q: "Apa itu civil society organizations (CSOs)?", a: "Organisasi di luar negara dan di luar pasar: LSM, serikat pekerja, kelompok agama, asosiasi komunitas, gerakan sosial. Ciri umumnya nirlaba, sukarela, dan mengejar tujuan kolektif." },
  { ch: 10, q: "Mengapa CSO adalah stakeholder yang khas?", a: "Mereka umumnya <strong>tidak punya hubungan transaksional</strong> dengan perusahaan. Kekuatannya bersifat <strong>moral dan reputasional</strong>: kuat pada <em>legitimacy</em> dan <em>urgency</em>, lemah pada <em>power</em> formal — sehingga membangun kekuatan lewat media, konsumen, dan investor." },
  { ch: 10, q: "Sebutkan empat peran CSO terhadap bisnis.", a: "<strong>Watchdog</strong> (mengawasi dan mengungkap), <strong>advocate</strong> (memperjuangkan perubahan kebijakan), <strong>representative</strong> (mewakili yang tidak bersuara), <strong>service provider & partner</strong>." },
  { ch: 10, q: "Apa isu akuntabilitas dan legitimasi NGO?", a: "Kepada siapa NGO bertanggung jawab — donor, anggota, atau komunitas yang diwakilinya? Atas dasar apa ia mengklaim mewakili pihak lain, mengingat tidak ada mekanisme pemilihan seperti pada pemerintah? Plus transparansi sumber dana." },
  { ch: 10, q: "Apa itu astroturfing?", a: "Membentuk gerakan warga <strong>palsu</strong> yang seolah-olah muncul spontan dari masyarakat, padahal disponsori dan dikendalikan pihak berkepentingan. Bentuk manipulasi opini publik yang menyamar sebagai partisipasi sipil." },
  { ch: 10, q: "Sebutkan tiga posisi hubungan bisnis–CSO beserta risikonya.", a: "<strong>Confrontation</strong> (tekanan tinggi, biaya tinggi), <strong>dialogue</strong> (risiko tokenism), <strong>partnership</strong> (risiko <em>co-optation</em> — CSO kehilangan ketajaman kritis karena bergantung pada dana atau relasi)." },
  { ch: 10, q: "Apa itu bluewashing?", a: "Perusahaan memakai kemitraan dengan LSM atau badan PBB sebagai <strong>tameng reputasi</strong> tanpa mengubah praktik bisnis intinya." },
  { ch: 10, q: "Sebutkan empat tingkat keterlibatan komunitas perusahaan.", a: "<strong>Charitable giving</strong> → <strong>community involvement</strong> (kesukarelawanan, berbagi keahlian) → <strong>strategic philanthropy</strong> (selaras kompetensi inti) → <strong>social investment / shared value</strong> (nilai sosial lewat model bisnis sendiri)." },
  { ch: 10, q: "Apa kritik utama terhadap filantropi korporat?", a: "Ia dapat menjadi <strong>pengalihan perhatian</strong>: menyumbang untuk pendidikan sambil melakukan penghindaran pajak yang mengurangi anggaran pendidikan publik. Filantropi tidak dapat menebus kerusakan yang ditimbulkan operasi utama." },
  { ch: 10, q: "Apa itu social enterprise dan risiko utamanya?", a: "Organisasi yang menggunakan model bisnis untuk mencapai <strong>misi sosial sebagai tujuan utama</strong>, dengan surplus terutama diinvestasikan kembali untuk misi itu. Risikonya: <strong>mission drift</strong> — tekanan komersial menggeser misi sosial." },

  /* ---- CM11 ---- */
  { ch: 11, q: "Mengapa posisi pemerintah unik di antara stakeholder?", a: "Ia sekaligus <strong>stakeholder</strong> (menerima pajak, berkepentingan atas lapangan kerja) dan <strong>pembuat aturan main</strong> bagi seluruh stakeholder lain." },
  { ch: 11, q: "Sebutkan lima alasan etis mengapa regulasi dibutuhkan.", a: "<strong>Eksternalitas</strong>, <strong>barang publik</strong>, <strong>asimetri informasi</strong>, <strong>kekuatan pasar/monopoli</strong>, dan <strong>tragedy of the commons</strong>." },
  { ch: 11, q: "Kapan lobi dapat diterima dan kapan bermasalah?", a: "<strong>Dapat diterima</strong>: terbuka dan tercatat, data jujur dan dapat diverifikasi, bersaing terbuka dengan kepentingan lain, berbicara atas nama sendiri. <strong>Bermasalah</strong>: rahasia, mendanai riset yang tampak independen, meniadakan suara pihak lemah, astroturfing." },
  { ch: 11, q: "Bedakan revolving door, regulatory capture, dan state capture.", a: "<strong>Revolving door</strong>: perpindahan orang antara regulator dan industri. <strong>Regulatory capture</strong>: regulator melayani kepentingan industri yang diawasinya. <strong>State capture</strong>: kepentingan swasta membentuk aturan negara secara sistematis." },
  { ch: 11, q: "Apa tiga akibat celah regulasi dalam globalisasi?", a: "<strong>Regulatory arbitrage</strong> (memindahkan operasi ke yurisdiksi paling longgar), <strong>race to the bottom</strong> (negara menurunkan standar demi investasi), <strong>governance gap</strong> (tidak ada otoritas penegak pada isu lintas batas)." },
  { ch: 11, q: "Sebutkan tangga respons dari hard law ke MSI.", a: "<strong>Hard law</strong> (regulasi mengikat, berhenti di batas negara) → <strong>self-regulation</strong> (standar sendiri, rentan konflik kepentingan) → <strong>soft law</strong> (UN Global Compact, OECD Guidelines, UNGP) → <strong>multi-stakeholder initiatives</strong> (Fairtrade, FSC, RSPO, EITI)." },
  { ch: 11, q: "Apa kerangka UN Guiding Principles on Business and Human Rights?", a: "<strong>Protect, Respect, Remedy</strong>: negara wajib <em>melindungi</em> HAM; perusahaan wajib <em>menghormati</em> HAM termasuk melakukan <strong>human rights due diligence</strong>; korban harus punya akses <em>pemulihan</em>." },
  { ch: 11, q: "Apa itu political CSR dan masalah demokratisnya?", a: "Korporasi mengambil peran yang tradisional menjadi kewenangan pemerintah — menyediakan barang publik, menetapkan standar. Masalahnya: korporasi <strong>tidak dipilih</strong> dan tidak dapat dicopot oleh mereka yang terdampak; layanan dapat ditarik sewaktu-waktu." },
  { ch: 11, q: "Sebutkan empat jenis instrumen regulasi untuk keberlanjutan.", a: "<strong>Harga</strong> (pajak karbon, perdagangan emisi), <strong>perintah</strong> (standar emisi, larangan bahan berbahaya), <strong>insentif</strong> (subsidi hijau, pengadaan berkelanjutan), <strong>informasi</strong> (label energi, pengungkapan jejak karbon)." },
  { ch: 11, q: "Apa kritik utama terhadap penggunaan SDGs oleh perusahaan?", a: "<strong>Cherry-picking</strong> atau <em>SDG-washing</em> — memilih tujuan yang mudah dan sudah selaras dengan bisnisnya, sambil mengabaikan tujuan yang justru paling terdampak operasinya." },

  /* ---- CM12 ---- */
  { ch: 12, q: "Sebutkan empat pendorong perubahan etika bisnis ke depan.", a: "<strong>Krisis iklim</strong> (dari isu reputasi menjadi risiko finansial), <strong>teknologi digital</strong>, <strong>pergeseran ekspektasi generasi</strong> pekerja dan konsumen, dan <strong>kembalinya regulasi</strong> setelah self-regulation dinilai tidak memadai." },
  { ch: 12, q: "Apa uji tiga pertanyaan untuk klaim stakeholder capitalism?", a: "(1) Apakah ada <strong>target terukur</strong> dengan tenggat? (2) Apakah <strong>remunerasi eksekutif</strong> terikat pada target itu? (3) Apakah ada pihak <strong>di luar perusahaan</strong> yang dapat menuntut pertanggungjawaban? Bila semuanya tidak, klaim itu belum punya mekanisme akuntabilitas." },
  { ch: 12, q: "Apa itu benefit corporation / B Corp?", a: "Bentuk hukum atau sertifikasi yang <strong>mengikat tujuan sosial dan lingkungan ke dalam anggaran dasar</strong>, sehingga direksi secara hukum wajib mempertimbangkannya — bukan sekadar pernyataan sukarela." },
  { ch: 12, q: "Sebutkan enam isu etis utama teknologi digital dan AI.", a: "<strong>Algorithmic bias</strong>, <strong>opacity/black box</strong>, <strong>accountability gap</strong>, <strong>surveillance & data</strong>, <strong>automation</strong> dan dampaknya pada kerja, serta <strong>dampak lingkungan</strong> pusat data." },
  { ch: 12, q: "Sebutkan enam prinsip etika AI yang mulai menjadi standar.", a: "<strong>Transparency & explainability</strong>, <strong>fairness & non-discrimination</strong>, <strong>accountability</strong>, <strong>privacy & data governance</strong>, <strong>human oversight</strong>, <strong>safety & robustness</strong>." },
  { ch: 12, q: "Apa itu double materiality?", a: "Pengungkapan harus mencakup dua arah: (1) <strong>financial materiality</strong> — bagaimana isu keberlanjutan memengaruhi nilai perusahaan; dan (2) <strong>impact materiality</strong> — bagaimana perusahaan memengaruhi manusia dan lingkungan. Kebanyakan perusahaan hanya melaporkan arah pertama." },
  { ch: 12, q: "Sebutkan kerangka pelaporan keberlanjutan terkini, termasuk Indonesia.", a: "<strong>CSRD</strong> (Uni Eropa, asurans wajib, double materiality), <strong>ISSB / IFRS S1–S2</strong>, <strong>TCFD</strong> (risiko iklim), dan di Indonesia <strong>POJK 51/2017</strong> tentang laporan keberlanjutan." },
  { ch: 12, q: "Apa tanda greenwashing yang paling sering terlewat?", a: "<strong>Ketidaksesuaian antara komitmen publik dan lobi kebijakan</strong> — perusahaan menjanjikan target iklim sementara asosiasi industrinya menentang regulasi iklim. Bandingkan apa yang dikatakan dengan apa yang diperjuangkan." },
  { ch: 12, q: "Apa empat kapasitas manajer yang etis?", a: "<strong>Sensitivitas</strong> (mengenali dimensi moral), <strong>penalaran</strong> (menganalisis dengan beberapa lensa), <strong>imajinasi moral</strong> (menemukan alternatif ketiga), <strong>keberanian</strong> (bertindak ketika ada biayanya)." },
  { ch: 12, q: "Empat pertanyaan refleksi sebelum keputusan besar?", a: "Siapa yang terdampak dan apakah mereka ikut bersuara? Bersediakah saya keputusan ini diberitakan terbuka? Akankah saya menerimanya bila berada di posisi pihak paling dirugikan? Akankah saya bangga menjelaskannya sepuluh tahun dari sekarang?" }
];

/* Glosarium istilah kunci — dapat dicari dan disaring per bab */
window.BEFS_GLOSSARY = [
  { ch: 1, term: "Business ethics", id: "Etika bisnis", def: "Studi tentang situasi, aktivitas, dan keputusan bisnis di mana isu benar dan salah dipertanyakan." },
  { ch: 1, term: "Morality", id: "Moralitas", def: "Norma, nilai, dan keyakinan yang tertanam dalam proses sosial dan mendefinisikan benar-salah bagi individu atau komunitas." },
  { ch: 1, term: "Ethical theory", id: "Teori etika", def: "Aturan dan prinsip hasil studi etika yang menentukan benar dan salah pada situasi tertentu." },
  { ch: 1, term: "Globalization", id: "Globalisasi", def: "Proses deterritorialization — aktivitas sosial, politik, dan ekonomi semakin terlepas dari batas wilayah geografis." },
  { ch: 1, term: "Ethical relativism", id: "Relativisme etis", def: "Pandangan bahwa tidak ada kebenaran moral universal; benar-salah bergantung pada konteks budaya." },
  { ch: 1, term: "Ethical absolutism", id: "Absolutisme etis", def: "Pandangan bahwa ada prinsip moral abadi yang berlaku di mana pun dan kapan pun." },
  { ch: 1, term: "Sustainability", id: "Keberlanjutan", def: "Pemeliharaan sistem jangka panjang menurut pertimbangan lingkungan, ekonomi, dan sosial." },
  { ch: 1, term: "Triple bottom line", id: "Tiga garis dasar", def: "Kerangka tiga dimensi keberlanjutan: environmental, economic, social — people, planet, profit (Elkington)." },
  { ch: 1, term: "Sustainable development", id: "Pembangunan berkelanjutan", def: "Pembangunan yang memenuhi kebutuhan masa kini tanpa mengorbankan kemampuan generasi mendatang memenuhi kebutuhannya (Brundtland, 1987)." },
  { ch: 1, term: "Social justice", id: "Keadilan sosial", def: "Keadilan distribusi manfaat dan beban pembangunan, baik dalam satu generasi maupun antargenerasi." },

  { ch: 2, term: "Corporate Internal Decision Structure", id: "Struktur keputusan internal korporasi", def: "Kombinasi bagan organisasi dan aturan pengakuan keputusan yang membuat korporasi dapat disebut pelaku moral (French)." },
  { ch: 2, term: "Corporate Social Responsibility", id: "Tanggung jawab sosial perusahaan", def: "Harapan ekonomi, hukum, etis, dan diskresioner masyarakat terhadap organisasi pada suatu waktu." },
  { ch: 2, term: "Carroll's CSR pyramid", id: "Piramida CSR Carroll", def: "Empat tingkat tanggung jawab: economic (required), legal (required), ethical (expected), philanthropic (desired)." },
  { ch: 2, term: "Stakeholder", id: "Pemangku kepentingan", def: "Kelompok atau individu yang dapat memengaruhi atau dipengaruhi oleh pencapaian tujuan organisasi (Freeman)." },
  { ch: 2, term: "Negative right", id: "Hak negatif", def: "Klaim yang mewajibkan pihak lain untuk tidak mengganggu — cukup membiarkan; misalnya privasi dan kebebasan berpendapat." },
  { ch: 2, term: "Positive right", id: "Hak positif", def: "Klaim yang mewajibkan pihak lain menyediakan fasilitas agar hak dapat dijalankan, bukan sekadar tidak mengganggu; misalnya hak atas pendidikan dasar." },
  { ch: 2, term: "Contractual rights and duties", id: "Hak dan kewajiban kontraktual", def: "Hak dan kewajiban korelatif yang lahir dari perjanjian antara pihak-pihak tertentu; sah secara moral bila ada pengetahuan penuh, tanpa misrepresentasi, tanpa paksaan, dan tidak mengikat pada tindakan tak bermoral." },
  { ch: 2, term: "Social costs", id: "Biaya sosial", def: "Biaya eksternal akibat aktivitas produksi yang menjadi beban masyarakat — polusi, kerusakan iklim; lawan dari private costs yang ditanggung perusahaan sendiri." },
  { ch: 2, term: "Internalizing external costs", id: "Internalisasi biaya eksternal", def: "Kewajiban memasukkan biaya sosial ke dalam perhitungan perusahaan (private + social costs) dan menghentikan polusi dengan alat pengendalinya." },
  { ch: 2, term: "Primary stakeholders", id: "Pemangku kepentingan primer", def: "Kelompok yang terlibat transaksi ekonomi langsung dengan perusahaan (market stakeholders) — karyawan, pemegang saham, kreditor, pelanggan, pemasok, distributor — sehingga kelangsungan perusahaan bergantung padanya." },
  { ch: 2, term: "Secondary stakeholders", id: "Pemangku kepentingan sekunder", def: "Kelompok yang tidak bertransaksi ekonomi langsung tetapi dapat memengaruhi atau dipengaruhi perusahaan (nonmarket) — pemerintah, komunitas, media, LSM, masyarakat umum." },
  { ch: 2, term: "Stakeholder salience", id: "Tingkat kepentingan stakeholder", def: "Model Mitchell, Agle & Wood: perhatian manajemen bergantung pada kombinasi power, legitimacy, dan urgency." },
  { ch: 2, term: "Definitive stakeholder", id: "Stakeholder definitif", def: "Stakeholder yang memiliki ketiga atribut sekaligus — power, legitimacy, dan urgency — sehingga menjadi prioritas utama." },
  { ch: 2, term: "Corporate accountability", id: "Akuntabilitas korporasi", def: "Kewajiban perusahaan mempertanggungjawabkan tindakannya kepada pihak yang terdampak." },
  { ch: 2, term: "Corporate citizenship", id: "Kewargaan korporasi", def: "Peran korporasi dalam mengelola hak kewarganegaraan individu — sosial, sipil, dan politik (extended view)." },
  { ch: 2, term: "Shareholder value", id: "Nilai pemegang saham", def: "Pandangan bahwa tujuan utama perusahaan adalah memaksimalkan nilai bagi pemegang saham (Friedman)." },

  { ch: 3, term: "Consequentialist ethics", id: "Etika konsekuensialis", def: "Kelompok teori yang menilai benar-salah berdasarkan hasil atau akibat tindakan; mencakup egoism dan utilitarianism." },
  { ch: 3, term: "Utilitarianism", id: "Utilitarianisme", def: "Tindakan benar bila menghasilkan kebaikan terbesar bagi jumlah orang terbanyak (Bentham, Mill)." },
  { ch: 3, term: "Egoism", id: "Egoisme", def: "Tindakan dapat diterima bila pengambil keputusan secara bebas mengejar kepentingannya sendiri, jangka pendek maupun panjang." },
  { ch: 3, term: "Categorical imperative", id: "Imperatif kategoris", def: "Prinsip Kant yang berlaku tanpa syarat, dirumuskan dalam tiga maksim: consistency, human dignity, universality." },
  { ch: 3, term: "Ethics of duty", id: "Etika kewajiban", def: "Teori Kant: tindakan bermoral bila dilakukan karena kewajiban dan sesuai prinsip rasional, bukan karena akibatnya." },
  { ch: 3, term: "Natural rights", id: "Hak kodrati", def: "Hak yang melekat pada manusia karena ia manusia, bukan karena diberikan negara (Locke)." },
  { ch: 3, term: "Veil of ignorance", id: "Tabir ketidaktahuan", def: "Eksperimen pikiran Rawls: merancang aturan masyarakat tanpa mengetahui posisi kita sendiri di dalamnya." },
  { ch: 3, term: "Difference principle", id: "Prinsip perbedaan", def: "Prinsip Rawls: ketimpangan sosial-ekonomi hanya dibenarkan bila memberi manfaat terbesar bagi yang paling tidak beruntung." },
  { ch: 3, term: "Virtue ethics", id: "Etika keutamaan", def: "Teori yang memusatkan penilaian pada karakter pelaku — bukan \"tindakan apa yang benar\" tetapi \"orang seperti apa saya seharusnya\"." },
  { ch: 3, term: "Discourse ethics", id: "Etika diskursus", def: "Teori Habermas: keabsahan moral lahir dari dialog yang setara, terbuka, dan bebas dominasi di antara pihak terdampak." },
  { ch: 3, term: "Ethical pluralism", id: "Pluralisme etis", def: "Pendekatan yang memakai beberapa teori sekaligus karena masing-masing menyorot aspek berbeda dari satu dilema." },

  { ch: 4, term: "Ethical decision-making model", id: "Model pengambilan keputusan etis", def: "Empat tahap Rest: recognize moral issue, make moral judgement, establish moral intent, engage in moral behaviour." },
  { ch: 4, term: "Ethical blindness", id: "Kebutaan etis", def: "Kegagalan menyadari bahwa sebuah situasi mengandung persoalan moral; ia dianggap keputusan teknis atau finansial belaka." },
  { ch: 4, term: "Moral intensity", id: "Intensitas moral", def: "Sejauh mana sebuah isu dipandang penting secara moral; enam komponen menurut Jones." },
  { ch: 4, term: "Proximity", id: "Kedekatan", def: "Komponen moral intensity: seberapa dekat korban dengan pengambil keputusan secara sosial, budaya, fisik, atau psikologis." },
  { ch: 4, term: "Cognitive moral development", id: "Perkembangan moral kognitif", def: "Model Kohlberg tentang enam tahap penalaran moral dalam tiga level; yang dinilai adalah alasan, bukan keputusannya." },
  { ch: 4, term: "Locus of control", id: "Lokus kendali", def: "Sejauh mana seseorang merasa mengendalikan peristiwa dalam hidupnya; memengaruhi penerimaan tanggung jawab moral." },
  { ch: 4, term: "Moral imagination", id: "Imajinasi moral", def: "Kemampuan membayangkan alternatif di luar pilihan yang tampak tersedia dan melihat situasi dari sudut pandang pihak lain." },
  { ch: 4, term: "Moral muteness", id: "Kebisuan moral", def: "Kecenderungan manajer menghindari bahasa moral karena dianggap tidak profesional, mengancam harmoni, dan mengurangi fleksibilitas." },
  { ch: 4, term: "Normalization of deviance", id: "Normalisasi penyimpangan", def: "Proses ketika pelanggaran kecil yang ditoleransi berulang kali membuat pelanggaran besar terasa wajar." },
  { ch: 4, term: "Ethical leadership", id: "Kepemimpinan etis", def: "Menunjukkan perilaku yang secara normatif pantas melalui tindakan pribadi dan relasi, sekaligus mendorongnya pada pengikut (Brown, Treviño & Harrison)." },
  { ch: 4, term: "Moral manager", id: "Manajer moral", def: "Dimensi ethical leadership yang menyangkut tindakan pada organisasi: menjadi role model, mengomunikasikan etika, menegakkan reward dan discipline." },

  { ch: 5, term: "Business ethics management", id: "Manajemen etika bisnis", def: "Upaya langsung perusahaan mengelola isu etis dan sosial melalui kebijakan, praktik, dan program spesifik." },
  { ch: 5, term: "Compliance-based approach", id: "Pendekatan berbasis kepatuhan", def: "Mencegah pelanggaran hukum lewat aturan rinci, pemantauan, dan sanksi (Paine)." },
  { ch: 5, term: "Integrity-based approach", id: "Pendekatan berbasis integritas", def: "Mendorong perilaku bertanggung jawab lewat nilai bersama, penilaian, dan kepemimpinan (Paine)." },
  { ch: 5, term: "Code of ethics", id: "Kode etik", def: "Pernyataan sukarela berisi komitmen pada nilai dan standar etis tertentu; jenisnya corporate, professional, industry, dan programme." },
  { ch: 5, term: "Whistleblowing", id: "Pengungkapan pelanggaran", def: "Pengungkapan oleh anggota organisasi atas praktik ilegal atau tidak bermoral di bawah kendali atasan, kepada pihak yang mampu bertindak." },
  { ch: 5, term: "Stakeholder dialogue", id: "Dialog pemangku kepentingan", def: "Pertukaran dua arah yang tulus di mana posisi perusahaan dapat berubah karena argumen pihak lain." },
  { ch: 5, term: "Tokenism", id: "Partisipasi semu", def: "Keterlibatan stakeholder yang hasilnya sudah ditentukan sebelumnya; menyerap kritik tanpa mengubah keputusan." },
  { ch: 5, term: "Social accounting", id: "Akuntansi sosial", def: "Proses mengumpulkan, menganalisis, dan mengomunikasikan informasi dampak sosial dan lingkungan kepada stakeholder." },
  { ch: 5, term: "External assurance", id: "Asurans independen", def: "Verifikasi laporan keberlanjutan oleh pihak ketiga independen; pembeda paling tajam antara laporan serius dan materi pemasaran." },
  { ch: 5, term: "Greenwashing", id: "Pencitraan hijau", def: "Klaim lingkungan atau sosial yang menyesatkan — melebih-lebihkan, memilih data menguntungkan, atau memakai citra hijau tanpa substansi." },
  { ch: 5, term: "GRI Standards", id: "Standar GRI", def: "Kerangka pelaporan keberlanjutan Global Reporting Initiative, berbasis materialitas dan dampak; paling luas dipakai." },

  { ch: 6, term: "Agency problem", id: "Masalah keagenan", def: "Persoalan yang timbul dari pemisahan kepemilikan dan kendali: perbedaan kepentingan dan asimetri informasi antara principal dan agent." },
  { ch: 6, term: "Agency cost", id: "Biaya keagenan", def: "Biaya yang dikeluarkan untuk memantau dan menyelaraskan kepentingan manajemen dengan pemegang saham." },
  { ch: 6, term: "Corporate governance", id: "Tata kelola perusahaan", def: "Sistem aturan, praktik, dan proses yang mengarahkan dan mengendalikan perusahaan serta mengatur relasi antar-organ dan stakeholder." },
  { ch: 6, term: "Unitary board", id: "Dewan satu tingkat", def: "Struktur Anglo-American di mana direktur eksekutif dan non-eksekutif duduk dalam satu dewan." },
  { ch: 6, term: "Two-tier board", id: "Dewan dua tingkat", def: "Struktur Kontinental dengan dewan pengawas terpisah dari dewan pelaksana; di Indonesia berupa Dewan Komisaris dan Direksi." },
  { ch: 6, term: "Codetermination", id: "Kodeterminasi", def: "Praktik Jerman berupa perwakilan pekerja di dewan pengawas perusahaan." },
  { ch: 6, term: "Insider trading", id: "Perdagangan orang dalam", def: "Memperdagangkan efek berdasarkan informasi material yang belum tersedia untuk publik." },
  { ch: 6, term: "Creative accounting", id: "Akuntansi kreatif", def: "Memanfaatkan celah standar akuntansi untuk menyajikan gambaran menyesatkan meski secara teknis sah." },
  { ch: 6, term: "Tax avoidance", id: "Penghindaran pajak", def: "Penyusunan struktur usaha yang sah secara hukum untuk meminimalkan pajak; berbeda dari tax evasion yang ilegal." },
  { ch: 6, term: "Socially Responsible Investment", id: "Investasi bertanggung jawab sosial", def: "Pendekatan investasi yang mempertimbangkan kriteria sosial, lingkungan, dan etika selain imbal hasil finansial." },
  { ch: 6, term: "Shareholder activism", id: "Aktivisme pemegang saham", def: "Penggunaan hak kepemilikan untuk memengaruhi perilaku perusahaan lewat resolusi RUPS, pemungutan suara, dialog, atau kampanye publik." },

  { ch: 7, term: "Due process", id: "Proses yang wajar", def: "Hak karyawan atas prosedur yang adil sebelum sanksi atau pemutusan: pemberitahuan, kesempatan membela diri, dan mekanisme banding." },
  { ch: 7, term: "Direct discrimination", id: "Diskriminasi langsung", def: "Perlakuan berbeda secara terang-terangan berdasarkan karakteristik yang tidak relevan dengan pekerjaan." },
  { ch: 7, term: "Indirect discrimination", id: "Diskriminasi tidak langsung", def: "Aturan yang tampak netral tetapi berdampak tidak proporsional pada kelompok tertentu." },
  { ch: 7, term: "Affirmative action", id: "Tindakan afirmatif", def: "Langkah aktif memperbaiki ketimpangan struktural melalui pelatihan khusus, target keberagaman, atau rekrutmen yang menjangkau kelompok kurang terwakili." },
  { ch: 7, term: "Glass ceiling", id: "Langit-langit kaca", def: "Hambatan tak terlihat yang menghalangi kelompok tertentu naik ke jenjang manajemen atas." },
  { ch: 7, term: "Living wage", id: "Upah layak", def: "Tingkat upah yang cukup memenuhi kebutuhan dasar pekerja dan keluarganya di lokasi tersebut; sering di atas upah minimum legal." },
  { ch: 7, term: "Freedom of association", id: "Kebebasan berserikat", def: "Hak pekerja membentuk dan bergabung dengan serikat serta berunding bersama; termasuk standar inti ILO." },
  { ch: 7, term: "Race to the bottom", id: "Perlombaan ke dasar", def: "Kekhawatiran bahwa persaingan menarik investasi mendorong negara menurunkan standar perlindungan pekerja dan lingkungan." },
  { ch: 7, term: "Just transition", id: "Transisi berkeadilan", def: "Prinsip bahwa peralihan menuju ekonomi rendah karbon tidak boleh meninggalkan pekerja sektor lama tanpa perlindungan." },
  { ch: 7, term: "Gig economy", id: "Ekonomi lepas", def: "Model kerja berbasis platform di mana pekerja diklasifikasikan sebagai mitra independen sehingga di luar jangkauan hak ketenagakerjaan." },

  { ch: 8, term: "Consumer sovereignty", id: "Kedaulatan konsumen", def: "Gagasan bahwa pilihan konsumen menentukan apa yang diproduksi; hanya nyata bila terpenuhi capability, information, dan choice." },
  { ch: 8, term: "Caveat emptor", id: "Pembeli waspada", def: "Prinsip lama bahwa risiko produk ada pada pembeli; kewajiban penjual hanya tidak berbohong secara aktif." },
  { ch: 8, term: "Due care", id: "Kehati-hatian yang wajar", def: "Kewajiban produsen mengambil langkah wajar mencegah bahaya dalam desain, produksi, pengujian, dan peringatan." },
  { ch: 8, term: "Strict liability", id: "Tanggung jawab mutlak", def: "Produsen bertanggung jawab atas cacat produk meskipun tidak terbukti lalai." },
  { ch: 8, term: "Puffery", id: "Pujian berlebihan", def: "Klaim promosi berlebihan yang tidak dimaksudkan dipercaya secara harfiah; umumnya dianggap sah." },
  { ch: 8, term: "Price gouging", id: "Pencatutan harga", def: "Menaikkan harga secara ekstrem saat kondisi darurat ketika konsumen tidak punya pilihan." },
  { ch: 8, term: "Predatory pricing", id: "Harga predatoris", def: "Menetapkan harga di bawah biaya untuk mematikan pesaing, lalu menaikkan harga setelah pasar dikuasai." },
  { ch: 8, term: "Dark patterns", id: "Pola gelap", def: "Desain antarmuka yang mengarahkan pengguna menyetujui atau membeli sesuatu tanpa benar-benar sadar." },
  { ch: 8, term: "Vulnerable consumers", id: "Konsumen rentan", def: "Konsumen yang kemampuannya memilih secara bebas dan terinformasi berkurang: anak, lansia, orang dengan literasi rendah, atau dalam kondisi darurat." },
  { ch: 8, term: "Bottom of the Pyramid", id: "Dasar piramida", def: "Segmen miliaran orang berpendapatan rendah yang dipandang Prahalad sebagai pasar terabaikan sekaligus mitra pembangunan." },
  { ch: 8, term: "Attitude–behaviour gap", id: "Kesenjangan sikap dan perilaku", def: "Konsumen menyatakan peduli lingkungan tetapi tetap membeli berdasarkan harga dan kenyamanan." },
  { ch: 8, term: "Planned obsolescence", id: "Keusangan terencana", def: "Merancang produk agar cepat usang atau sulit diperbaiki sehingga konsumen membeli ulang lebih cepat." },

  { ch: 9, term: "Bribery", id: "Penyuapan", def: "Menawarkan, menjanjikan, memberi, menerima, atau meminta keuntungan sebagai imbalan atas tindakan ilegal, tidak etis, atau melanggar kepercayaan." },
  { ch: 9, term: "Corruption", id: "Korupsi", def: "Penyalahgunaan kekuasaan yang dipercayakan untuk keuntungan pribadi; lebih luas daripada penyuapan." },
  { ch: 9, term: "Facilitation payment", id: "Uang pelicin", def: "Pembayaran kecil untuk mempercepat layanan rutin yang memang menjadi hak pembayar; dilarang UK Bribery Act dan hukum Indonesia." },
  { ch: 9, term: "Competitive intelligence", id: "Intelijen kompetitif", def: "Pengumpulan dan analisis informasi pesaing dari sumber yang tersedia secara sah dan terbuka." },
  { ch: 9, term: "Industrial espionage", id: "Spionase industri", def: "Memperoleh rahasia pesaing dengan cara tidak sah: meretas, mencuri dokumen, atau menyamar." },
  { ch: 9, term: "Cartel", id: "Kartel", def: "Kesepakatan antarpesaing untuk menetapkan harga, membagi wilayah pasar, atau mengatur pemenang tender." },
  { ch: 9, term: "Abuse of dominant position", id: "Penyalahgunaan posisi dominan", def: "Perusahaan dominan memakai posisinya untuk menghalangi persaingan, misalnya lewat tying atau predatory pricing." },
  { ch: 9, term: "Extended responsibility", id: "Tanggung jawab yang diperluas", def: "Tanggung jawab perusahaan meluas ke seluruh rantai nilai, melampaui batas kepemilikan hukumnya." },
  { ch: 9, term: "Fairtrade", id: "Perdagangan adil", def: "Sistem sertifikasi yang menjamin harga minimum, premium komunitas, relasi jangka panjang, serta standar kerja dan lingkungan bagi produsen." },
  { ch: 9, term: "Circular economy", id: "Ekonomi sirkular", def: "Model ekonomi di mana keluaran satu proses menjadi masukan proses lain, menggantikan pola linier take-make-dispose." },
  { ch: 9, term: "Industrial ecology", id: "Ekologi industri", def: "Perancangan kawasan industri agar limbah dan panas satu pabrik menjadi bahan baku dan energi pabrik lain." },
  { ch: 9, term: "Extended producer responsibility", id: "Tanggung jawab produsen diperluas", def: "Kewajiban produsen atas produknya hingga akhir masa pakai, termasuk pengumpulan dan pengolahannya." },

  { ch: 10, term: "Civil society organization", id: "Organisasi masyarakat sipil", def: "Organisasi di luar negara dan pasar: LSM, serikat pekerja, kelompok agama, gerakan sosial; nirlaba dan sukarela." },
  { ch: 10, term: "Co-optation", id: "Ko-optasi", def: "Situasi ketika CSO kehilangan ketajaman kritisnya karena bergantung pada dana atau relasi dengan perusahaan." },
  { ch: 10, term: "Astroturfing", id: "Gerakan warga palsu", def: "Membentuk gerakan yang tampak spontan dari masyarakat padahal disponsori dan dikendalikan pihak berkepentingan." },
  { ch: 10, term: "Bluewashing", id: "Pencitraan biru", def: "Memakai kemitraan dengan LSM atau badan PBB sebagai tameng reputasi tanpa mengubah praktik bisnis inti." },
  { ch: 10, term: "Strategic philanthropy", id: "Filantropi strategis", def: "Program sosial yang selaras dengan kompetensi inti dan kepentingan bisnis jangka panjang perusahaan." },
  { ch: 10, term: "Shared value", id: "Nilai bersama", def: "Menciptakan nilai ekonomi sekaligus nilai sosial melalui model bisnis itu sendiri, bukan lewat program terpisah." },
  { ch: 10, term: "Social enterprise", id: "Usaha sosial", def: "Organisasi yang memakai model bisnis untuk mencapai misi sosial, dengan surplus terutama diinvestasikan kembali untuk misi itu." },
  { ch: 10, term: "Mission drift", id: "Pergeseran misi", def: "Risiko pada social enterprise ketika tekanan komersial perlahan menggeser misi sosialnya." },

  { ch: 11, term: "Externalities", id: "Eksternalitas", def: "Biaya atau manfaat yang ditanggung pihak ketiga dan tidak tercermin dalam harga pasar; alasan utama regulasi." },
  { ch: 11, term: "Tragedy of the commons", id: "Tragedi milik bersama", def: "Sumber daya bersama habis karena tiap pihak mengejar kepentingannya sendiri tanpa aturan pembatas." },
  { ch: 11, term: "Revolving door", id: "Pintu putar", def: "Perpindahan orang antara jabatan regulator dan industri yang diaturnya; menimbulkan konflik kepentingan." },
  { ch: 11, term: "Regulatory capture", id: "Pembajakan regulator", def: "Regulator lama-kelamaan melayani kepentingan industri yang diawasinya, bukan kepentingan publik." },
  { ch: 11, term: "State capture", id: "Pembajakan negara", def: "Kepentingan swasta membentuk aturan dan kebijakan negara secara sistematis untuk keuntungannya sendiri." },
  { ch: 11, term: "Regulatory arbitrage", id: "Arbitrase regulasi", def: "Memindahkan operasi, laba, atau domisili ke yurisdiksi dengan aturan paling menguntungkan." },
  { ch: 11, term: "Soft law", id: "Hukum lunak", def: "Norma internasional yang tidak mengikat secara hukum, seperti UN Global Compact dan OECD Guidelines for MNEs." },
  { ch: 11, term: "Multi-stakeholder initiative", id: "Inisiatif multi-pihak", def: "Standar yang disusun bersama bisnis, LSM, serikat pekerja, dan pemerintah; misalnya Fairtrade, FSC, RSPO, EITI." },
  { ch: 11, term: "UN Guiding Principles", id: "Prinsip Panduan PBB", def: "Kerangka Protect, Respect, Remedy untuk bisnis dan hak asasi manusia, termasuk kewajiban human rights due diligence." },
  { ch: 11, term: "Political CSR", id: "CSR politis", def: "Situasi ketika korporasi mengambil peran yang tradisional menjadi kewenangan pemerintah, seperti menyediakan barang publik atau menetapkan standar." },
  { ch: 11, term: "Sustainable Development Goals", id: "Tujuan Pembangunan Berkelanjutan", def: "17 tujuan PBB yang disepakati 2015 dengan target 2030; bagi bisnis menjadi bahasa bersama memetakan kontribusi dan dampak." },

  { ch: 12, term: "Corporate purpose", id: "Tujuan korporasi", def: "Pernyataan tujuan perusahaan melampaui laba yang dijadikan dasar pengambilan keputusan, bukan sekadar kalimat di laporan tahunan." },
  { ch: 12, term: "Stakeholder capitalism", id: "Kapitalisme pemangku kepentingan", def: "Gagasan bahwa perusahaan melayani seluruh stakeholder; dikritik karena sering tanpa mekanisme akuntabilitas yang mengikat." },
  { ch: 12, term: "Benefit corporation", id: "Korporasi manfaat", def: "Bentuk hukum atau sertifikasi yang mengikat tujuan sosial dan lingkungan ke dalam anggaran dasar perusahaan." },
  { ch: 12, term: "Algorithmic bias", id: "Bias algoritmik", def: "Sistem yang dilatih pada data historis mereproduksi diskriminasi masa lalu dalam rekrutmen, kredit, atau penegakan hukum." },
  { ch: 12, term: "Black box problem", id: "Masalah kotak hitam", def: "Keputusan sistem otomatis yang tidak dapat dijelaskan, sehingga bertabrakan dengan hak atas due process." },
  { ch: 12, term: "Double materiality", id: "Materialitas ganda", def: "Prinsip pengungkapan dua arah: dampak isu keberlanjutan pada perusahaan, dan dampak perusahaan pada manusia serta lingkungan." },
  { ch: 12, term: "TCFD", id: "Kerangka pengungkapan iklim", def: "Task Force on Climate-related Financial Disclosures: tata kelola, strategi, manajemen risiko, serta metrik dan target iklim." },
  { ch: 12, term: "CSRD", id: "Direktif pelaporan keberlanjutan UE", def: "Kewajiban pelaporan keberlanjutan Uni Eropa dengan asurans wajib dan penerapan double materiality." },
  { ch: 12, term: "POJK 51/2017", id: "Aturan laporan keberlanjutan Indonesia", def: "Peraturan OJK yang mewajibkan laporan keberlanjutan bagi lembaga jasa keuangan, emiten, dan perusahaan publik." },
  { ch: 12, term: "Human oversight", id: "Pengawasan manusia", def: "Prinsip etika AI bahwa manusia tetap dapat meninjau dan membatalkan keputusan sistem otomatis yang berisiko tinggi." }
];
